using System.Text.Json.Serialization;

namespace RA3MT.Core.Model;

/// <summary>One built-in reinforcement-code row: a GameObject's internal name,
/// its localized display name and its WB string hash (the "reinforcement
/// code"). Generated by tools/analysis/gen_reinforce_table.py from the game's
/// own archives — never hand-edited.</summary>
public sealed class ReinforcementEntry
{
    [JsonPropertyName("n")] public string Name { get; set; } = "";
    [JsonPropertyName("zh")] public string Zh { get; set; } = "";
    [JsonPropertyName("code")] public string Code { get; set; } = "";

    public uint Hash => Convert.ToUInt32(Code, 16);

    /// <summary>Picker display line.</summary>
    public string Display => $"{Zh}  ·  {Name}";
}

/// <summary>The embedded unit code table behind the reinforcement picker.
/// Accepts a raw 8-hex code, an internal name ("AlliedMCV") or a localized
/// name, so manual codes from community guides keep working.</summary>
public sealed class ReinforcementCatalog
{
    private readonly Dictionary<string, ReinforcementEntry> _byName;
    private readonly Dictionary<string, ReinforcementEntry> _byZh;
    private readonly Dictionary<string, ReinforcementEntry> _byCode;

    public IReadOnlyList<ReinforcementCategory> Categories { get; }
    public IReadOnlyList<ReinforcementEntry> Entries { get; }

    public ReinforcementCatalog(IReadOnlyList<ReinforcementCategory> categories)
    {
        Categories = categories;
        Entries = categories.SelectMany(c => c.Items).ToList();
        _byName = Entries.ToDictionary(e => e.Name, StringComparer.OrdinalIgnoreCase);
        _byZh = Entries.GroupBy(e => e.Zh, StringComparer.OrdinalIgnoreCase)
            .ToDictionary(g => g.Key, g => g.First(), StringComparer.OrdinalIgnoreCase);
        _byCode = Entries.ToDictionary(e => e.Code, StringComparer.OrdinalIgnoreCase);
    }

    public static ReinforcementCatalog Default { get; } = LoadEmbedded();

    private static ReinforcementCatalog LoadEmbedded()
    {
        var asm = typeof(ReinforcementCatalog).Assembly;
        using var s = asm.GetManifestResourceStream("RA3MT.Core.Data.reinforcement_codes.json")
                      ?? throw new InvalidOperationException("embedded reinforcement_codes.json not found");
        var data = System.Text.Json.JsonSerializer.Deserialize<ReinforcementData>(s)
                   ?? throw new InvalidOperationException("reinforcement_codes.json failed to deserialize");
        return new ReinforcementCatalog(data.Categories);
    }

    /// <summary>Resolve user input to a hash: hex code, internal name or
    /// localized name. Unknown input returns false.</summary>
    public bool TryResolve(string? input, out uint hash, out ReinforcementEntry? entry)
    {
        entry = null;
        if (string.IsNullOrWhiteSpace(input))
        {
            hash = 0;
            return false;
        }
        var text = input.Trim();
        ReinforcementEntry? match = null;
        if (_byCode.TryGetValue(text, out var byCode)) match = byCode;
        else if (_byName.TryGetValue(text, out var byName)) match = byName;
        else if (_byZh.TryGetValue(text, out var byZh)) match = byZh;
        if (match is not null)
        {
            entry = match;
            hash = match.Hash;
            return true;
        }
        // fall back to a raw hex code the user typed from a community guide
        if (TryParseHex(text, out hash) && hash != 0)
        {
            var want = hash;
            entry = Entries.FirstOrDefault(e => e.Hash == want);
            return true;
        }
        return false;
    }

    /// <summary>"6586A5A0" / "0x6586A5A0" style code (same grammar as the
    /// spawn actions' parser; duplicated to keep the model layer
    /// self-contained).</summary>
    private static bool TryParseHex(string text, out uint hash)
    {
        hash = 0;
        if (text.StartsWith("0x", StringComparison.OrdinalIgnoreCase))
            text = text[2..];
        return text.Length is >= 1 and <= 8
               && uint.TryParse(text, System.Globalization.NumberStyles.HexNumber,
                   System.Globalization.CultureInfo.InvariantCulture, out hash);
    }

    /// <summary>Case-insensitive substring search over both names — feeds the
    /// picker's filter box.</summary>
    public IEnumerable<ReinforcementEntry> Search(string text)
    {
        if (string.IsNullOrWhiteSpace(text)) return Entries;
        return Entries.Where(e =>
            e.Name.Contains(text, StringComparison.OrdinalIgnoreCase)
            || e.Zh.Contains(text, StringComparison.OrdinalIgnoreCase));
    }
}

public sealed class ReinforcementCategory
{
    [JsonPropertyName("id")] public string Id { get; set; } = "";
    [JsonPropertyName("name")] public string Name { get; set; } = "";
    [JsonPropertyName("items")] public List<ReinforcementEntry> Items { get; set; } = new();
}

/// <summary>JSON root of assets/reinforcement_codes.json.</summary>
public sealed class ReinforcementData
{
    [JsonPropertyName("source")] public string Source { get; set; } = "";
    [JsonPropertyName("categories")] public List<ReinforcementCategory> Categories { get; set; } = new();
}
